// 由 tools/gen_reanim.py 从 assets/reanim/manifest.json 生成，请勿手改。
// 原版 reanim（12fps）逐帧烘焙的格子图集元数据：每个 clip 是 cols x rows 的网格，
// 单元格 w x h 像素；角色锚点 (ax, ay) 是 reanim 原点（脚底）在单元格内的位置。

#[derive(Clone, Copy)]
pub struct Clip {
    pub ok: bool,
    pub slot: u16,
    pub frames: u16,
    pub cols: u16,
    pub rows: u16,
    pub w: f32,
    pub h: f32,
    pub fps: f32,
}

impl Clip {
    pub const NONE: Clip = Clip { ok: false, slot: 0, frames: 0, cols: 1, rows: 1, w: 0.0, h: 0.0, fps: 12.0 };
}

pub struct Char {
    pub name: &'static str,
    pub w: f32,
    pub h: f32,
    pub ax: f32,
    pub ay: f32,
    pub base: Clip,
    pub shoot: Clip,
    pub eat: Clip,
    pub die: Clip,
    pub special: Clip,
}

impl Char {
    pub fn has(&self, clip: &Clip) -> bool {
        clip.ok && clip.frames > 0 && clip.w > 0.0 && self.h > 0.0
    }
}

